class Solution {
public:
    long long minMergeCost(vector<vector<int>>& lists) {
        int m = lists.size(), size = 1 << m;
        vector<int> length(size, 0), median(size, 0);
        for (int mask = 1; mask < size; ++mask) {
            vector<int> values;
            for (int i = 0; i < m; ++i) if (mask & (1 << i))
                values.insert(values.end(), lists[i].begin(), lists[i].end());
            sort(values.begin(), values.end());
            length[mask] = values.size();
            median[mask] = values[(values.size() - 1) / 2];
        }
        const long long INF = LLONG_MAX / 4;
        vector<long long> dp(size, INF);
        for (int i = 0; i < m; ++i) dp[1 << i] = 0;
        for (int mask = 1; mask < size; ++mask) {
            if (!(mask & (mask - 1))) continue;
            for (int a = (mask - 1) & mask; a; a = (a - 1) & mask) {
                int b = mask ^ a;
                if (a > b) continue;
                long long cost = length[mask] + llabs((long long)median[a] - median[b]);
                dp[mask] = min(dp[mask], dp[a] + dp[b] + cost);
            }
        }
        return dp[size - 1];
    }
};
